@startuml

class Artist {
  + Name : string
  + DateOfBirth : date
  + WebsiteURL : string
}

class Song {
  + Title : string
  + Year : int
  + Length : int
  + Genre : string
}

class User {
  + UserID : int
  + Name : string
  + Address : string
}

class BusinessUser extends User {
  + VATNumber : string
}

class RegularUser extends User {}

class Single {}

class Hit {}

class Album {
  + TrackNumber : int
}

Artist "1" -- "*" Song : belongs to
BusinessUser "1" -- "*" Song : uploads
RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : composes
Album "1" *-- "1..*" Hit : consists of
Single "1" -- "0..1" Hit : is a type of
Hit "1" -- "0..1" Single : is a type of

@enduml

